const HotspotOp *hotspotProgramForRoom(int room, uint &count) {
	count = 0;
	for (uint i = 0; i < ARRAYSIZE(kHotspotRooms); i++) {
		if (kHotspotRooms[i].room != room)
			continue;
		count = kHotspotRooms[i].count;
		return &kHotspotOps[kHotspotRooms[i].first];
	}
	return nullptr;
}

uint hotspotVarCount() {
	return ARRAYSIZE(kHotspotVars);
}

uint16 hotspotVarAddr(uint index) {
	return index < ARRAYSIZE(kHotspotVars) ? kHotspotVars[index] : 0;
}

